"""Editable editorial copy. This describes installed checkpoint HR, not a final release."""

PROFILES=[
dict(key='mario',name='MARIO & LUIGI',kicker='THE ORIGINAL ROUTE MASTERS',color='#d93734',number='01',
 intro='A familiar jump can take you a long way. Mario mixes momentum, short hops and running leaps. Luigi shares the classic toolkit, with a little extra lift and a little less grip.',
 controls=[('A','Jump; release to shorten the rise.'),('B + direction','Run. At fire power, B also throws a bouncing fireball.'),('Down','Crouch in a large form; enter an appropriate pipe.'),('Select at Mario portrait','Switch Mario and Luigi before starting.')],
 easy='Mario uses the linked 1.0 movement rules, including a lower walking cap and a jump that responds immediately to release. Ordinary descending stomps remain your basic attack.',
 hard='Mario uses the 2.02 movement path: a faster walk, a minimum initial jump rise, and height rules that reward running. He still stomps. Luigi keeps his requested native Mario-style movement in both modes.',
 upgrades='Mushroom: large form. Next growth pickup: fire form. Fireballs bounce along the ground and preserve masonry. Neither brother has a selectable special-weapon inventory.',
 tips=[('BUILD YOUR RUN','Start accelerating before the edge. A late takeoff spends more of the jump above the gap.'),('LUIGI BRAKES EARLY','His slightly lower traction makes a tiny platform feel smaller. Ease off sooner than with Mario.'),('WATER RHYTHM','Tap A repeatedly to paddle. B does not turn swimming into a run.')],
 sources=['src/mario_source.s','src/expanded.s','src/character_select.s','docs/reference/water.md']),
dict(key='megaman',name='MEGA MAN',kicker='CHARGE. SLIDE. ADAPT.',color='#087fbf',number='02',
 intro='Helmet off, buster ready. Mega Man starts with three ordinary shots and earns charging with his first growth upgrade. His slide is as useful for low routes as his cannon is for clearing the road.',
 controls=[('A','Jump; hold for a fuller rise.'),('Down + A','Slide along the ground, including underwater.'),('B','Fire. With charging available, hold and release for a charged shot.'),('Select / pause + Left/Right','Hard: cycle owned weapons / choose either direction.')],
 easy='The original three-tier route: helmetless buster, helmet and charge, then stronger fire-colored shots. No collectible 2.02 arsenal or energy drops. A classic slide cannot be jump-cancelled in open space.',
 hard='The 2.02 movement path adds the walking startup step and allows a jump out of a clear slide. Mushroom grants charging; later blocks reveal individual weapons. Rush Coil is Mega Man-only.',
 upgrades='Hard arsenal: Super Arm, Metal Blade, Hard Knuckle, Pharaoh Shot, Charge Kick, Flame Blast, Water Shield, Rush Coil and the passive Energy Balancer. See the workshop on page 8.',
 tips=[('TWO SHOTS, ONE BRICK','An ordinary buster pellet does not smash a brick in one hit. Fire a second shot at the same masonry.'),('TAKE THE HIGH ROAD','With Rush selected, B summons him; Up+B places him overhead. Land on him for a spring.'),('KEEP A RESERVE','Rush needs at least 4 energy to appear. His spring spends 12, stopping at zero.')],
 sources=['src/megaman_physics.s','src/megaman_weapons.s','src/megaman_rush.s','tools/reference/build_inventory.py']),
dict(key='bass',name='BASS',kicker='DOUBLE JUMP. BIG ARSENAL.',color='#b78319',number='03',
 intro='Bass is a gunner with a second chance in midair. His directional buster and dash-jump reward deliberate positioning. A mushroom gives an extra on-screen shot, not a charge attack.',
 controls=[('A, release, A','Jump, then use one second jump before landing.'),('Down + A','Dash on the ground. Release A, then press it again during the dash to jump.'),('Hold B + direction','Automatic buster fire and directional aim.'),('Select','Cycle acquired weapons, including back to the normal buster.')],
 easy='Bass was added after the six-character original. He keeps the modern inventory, double jump and dash in Easy. Easy adds ordinary enemy stomps; it does not replace his arsenal with a three-tier buster.',
 hard='Keep the same movement and equipment, but ordinary body landings are dangerous. Shoot before contact. A paid Charge Kick is a special attack, not permission to land on every hazard.',
 upgrades='Mushroom raises the buster limit from 3 shots to 4. Seven separately collected weapons and Energy Balancer follow. Bass does not acquire Mega Man\'s charge shot or Rush Coil.',
 tips=[('DASH, RELEASE, JUMP','Holding A through a dash is not a new jump press. Re-press it while the grounded dash is still active.'),('AIM BEFORE FIRE','Bass\'s ground firing stance restricts movement. Set the direction, shoot the lane, then advance.'),('WATCH THE ICON','A color change alone is not your weapon selector. Read the HUD icon, weapon name and energy.')],
 sources=['src/expanded.s','src/expanded_weapons.s','src/special_weapons.s','src/megaman_super_arm.s','tools/reference/build_inventory.py']),
dict(key='samus',name='SAMUS ARAN',kicker='TURN THE ROUTE INTO A TOOLBOX',color='#d96a18',number='04',
 intro='Beam range, a compact ball and attack upgrades open different approaches. Easy starts with the classic Morph Ball; Hard makes Morph Ball one of the items you collect.',
 controls=[('A','Jump. In Morph Ball, A exits the ball rather than jumping.'),('Down','Easy: Morph Ball. Hard: crouch, then press Down again after acquiring Morph Ball.'),('B / Up+B','Fire the beam / fire upward. In ball form, B plants a bomb.'),('Select / Down+Select','Hard: fire a missile / toggle B into missile mode.')],
 easy='Short Beam becomes Long Beam, then Wave Beam through growth pickups. Morph Ball and bombs are available without an inventory item. Her first two upright suits can head-break bricks; the fully powered form bumps them.',
 hard='Mushroom gives Long Beam. Collect Morph Ball, missiles, Ice or Wave Beam, Varia and Screw Attack separately. Her upright head bumps bricks in every Hard suit. Ordinary enemy landings hurt unless a valid special body attack protects her.',
 upgrades='Ice freezes surviving enemies and can make them temporary footholds. Wave changes the beam. Varia protects against firebars. Screw Attack damages eligible enemies during an active spin. Missile stock has a 20 maximum.',
 tips=[('UNMORPH WITH ROOM','A low ceiling can prevent standing up. Roll clear before trying to jump.'),('SPIN IS THE ATTACK','Screw Attack protection belongs to the active spinning jump; ordinary standing contact is still unsafe.'),('BOMBS ARE TOOLS','Use the blast for breakable masonry and bomb lifts. Pipes and the foundation are not normal bricks.')],
 sources=['src/samus.s','src/samus_weapons.s','src/remaining_weapons.s','src/megaman_weapons.s','tools/reference/build_inventory.py']),
dict(key='bill',name='BILL & LANCE',kicker='TWO COMMANDOS. ONE SHARED TOOLKIT.',color='#cb303b',number='05',
 intro='The Contra brothers turn the Mushroom Kingdom into a firing range. Angle the gun before an enemy closes in, and choose the right rule set before starting: Easy and Hard have very different reward paths.',
 controls=[('A','Jump with a committed arc.'),('B + D-pad','Fire horizontally, vertically or diagonally.'),('Down','Lie low and fire while crouched.'),('Select at Bill portrait','Choose Lance. A Hard gun pickup equips the replacement gun.')],
 easy='Normal gun -> mushroom Machine Gun -> flower Spread. Machine Gun is automatic while B is held; spread fires a fan. Powered Bill and Lance can survive an ordinary hit by losing their power. They can stomp eligible enemies.',
 hard='Mushroom does not automatically grant Machine Gun. Find Machine Gun, Spread, Laser and Flare as separate pickups, plus two Rapid upgrades. Contact is lethal in every power form. Use weapons instead of ordinary stomps.',
 upgrades='Laser launches a four-segment beam. Flare circles around a moving center. Rapid upgrades increase bullet speed independently of the gun. Hard gun pickups replace each other; they are not a retained Mega Man-style weapon wheel.',
 tips=[('MACHINE GUN IS MODE-SPECIFIC','Yes, the mushroom gives it in Easy. In Hard, the matching gun pickup is required.'),('LASER HAS A RHYTHM','A new laser burst replaces the old burst. Place your aim rather than mashing blindly.'),('LANCE IS A REAL ALTERNATE','His graphics differ; movement, gun rules and damage rules match Bill.')],
 sources=['src/roster_weapons.s','src/remaining_weapons.s','src/guest_body_contact.s','src/character_select.s','src/bill_source_body.s']),
dict(key='link',name='LINK',kicker='THE SWORD IS YOUR LANDING PLAN',color='#338341',number='06',
 intro='Link works close to the action. His sword, aerial thrusts and returning boomerang turn a cramped ledge into a tactical space. Learn the movement change between modes before judging a jump.',
 controls=[('A / B','Jump / swing the sword.'),('Up or Down in the air','Hold a sword thrust in the chosen vertical direction.'),('Select','Use boomerang in Easy; use the selected special in Hard.'),('Start, Left/Right, Start','Hard: pause, choose an owned special, resume.')],
 easy='Three sword tiers, with sword beams at the top tier; the original boomerang is available without an inventory hunt. Link accelerates and carries momentum. Sword contact takes its original priority before ordinary body contact.',
 hard='More immediate left/right movement replaces the original acceleration. Mushroom adds the short boomerang; blocks supply bow, bombs, magic boomerang and rings. Ordinary body contact is dangerous, so use a valid sword attack or thrust.',
 upgrades='Bow and bombs each use their own supply, capped at 20. Red Ring improves the powered sword state; Blue Ring protects Link from his own bomb. Select uses the chosen special, while B remains the sword.',
 tips=[('POINT THE THRUST','Downward sword contact and an ordinary falling body are different. Get the blade out before the enemy reaches you.'),('EASY HAS MOMENTUM','Release earlier when landing on a small ledge. Hard starts and stops more directly.'),('RESPECT YOUR BOMB','Without Blue Ring, give your own blast room.')],
 sources=['src/roster.s','src/roster_weapons.s','src/easy_lsr.s','src/easy_link_order.s','tools/reference/build_inventory.py']),
dict(key='simon',name='SIMON BELMONT',kicker='THE SECOND JUMP IS NOT OPTIONAL',color='#a17833',number='07',
 intro='Simon\'s first jump looks modest beside a tall pipe. His answer is already built in: release A and jump again in midair. The whip covers space ahead while subweapons work around obstacles.',
 controls=[('A, release, A','Jump, then double jump before landing.'),('B / Down+B','Whip standing / whip while crouched.'),('Select or Up+B','Easy: throw an axe. Hard: use the selected subweapon.'),('Pause + Left/Right','Hard: change the acquired subweapon.')],
 easy='Short whip -> Morning Star -> flame whip. Axes are available without heart management, with more simultaneous axes at higher tiers. Easy also uses the original committed air movement and ordinary stomps.',
 hard='Collect whip upgrades and subweapons individually. Axe, dagger, cross and holy water spend one heart; stopwatch spends five. Double Shot and Triple Shot raise the simultaneous subweapon allowance. Ordinary landings are unsafe.',
 upgrades='The stopwatch stops enemy movement for about three seconds of active game updates. Hearts share a 99 maximum. Small and large heart pickups restore 1 and 5. Whip attacks remain available without spending hearts.',
 tips=[('CLEAR THAT PIPE','Keep the second jump for the upper half of the obstacle. A fresh press is required; holding A cannot trigger it.'),('ARC OR LINE?','An axe reaches over an obstacle; a dagger reaches forward. Choose the route, then the tool.'),('LAND AND RESET','Walking off support leaves the second jump available. Landing resets the air-jump opportunity.')],
 sources=['src/roster.s','src/easy_lsr.s','src/remaining_weapons.s','src/roster_weapons.s','tools/reference/build_inventory.py']),
dict(key='pit',name='PIT',kicker='ARROWS FIRST. WINGS WHEN YOU NEED THEM.',color='#d78080',number='08',
 intro='Pit is a ROM guest addition, not a finished member of the 2.02 roster. His compact bow and flower-level wing flight offer a different way to manage vertical routes.',
 controls=[('A / B','Jump / fire an arrow.'),('Down+B / Up+B','Fire while ducking / fire upward.'),('Select','Swing the hammer.'),('At flower power: release, A','Start flight in midair; hold A to spend remaining lift.')],
 easy='Short arrows -> long arrows -> fire arrows plus flight. Easy allows ordinary stomps. Pit keeps the same requested bow, hammer and flight progression rather than gaining a made-up 1.0 inventory.',
 hard='The bow, hammer and flight remain available at the same power tiers. Ordinary body landings become unsafe. Hit enemies with an arrow or hammer, and use flight to avoid an unwanted landing.',
 upgrades='Two arrows can be active. Flower flight supplies up to 60 active updates of lift, roughly one second before slowdown. Releasing A pauses its use; landing restores the budget. Flight cannot activate underwater.',
 tips=[('SAVE THE FLAP','Jump normally first. A new midair A press starts the wing lift, so use it after gaining height.'),('TOUCH DOWN TO REFILL','A safe platform is a flight recharge station. Plan a chain of landings instead of one endless flight.'),('WATCH THE ROOF','Wings do not let Pit pass through ceilings. Release and reposition.')],
 sources=['src/expanded.s','src/expanded_weapons.s','docs/qa/walk-flight-update.md']),
dict(key='rygar',name='RYGAR',kicker='ONE THROW. A WHOLE LANE.',color='#cc5142',number='09',
 intro='The Diskarmor is a returning weapon with a visible chain. Think in complete throws: its outward sweep, wall turnaround and return are one attack, not a rapid-fire gun.',
 controls=[('A','Jump.'),('B / Down+B','Throw standing / throw while crouched.'),('Wait for the return','Only one Diskarmor throw is active at a time.'),('Select','No separate Rygar special attack is assigned.')],
 easy='Mushroom and flower increase Diskarmor reach. Easy adds ordinary stomps. Rygar retains the ROM\'s native-reference movement and returning-disk mechanics in both behavior settings.',
 hard='The same reach progression and attack remain. Ordinary body landings hurt: let the disk clear the lane before you commit to it. There is no invented 2.02 Rygar weapon inventory.',
 upgrades='The three maximum reaches are 40, 64 and 88 NES pixels. The disk retracts toward Rygar and begins returning after wall contact. An enemy is damaged once per throw, so do not count on repeated contact as it comes home.',
 tips=[('DUCK AND SEND IT','A low throw can reach an enemy while keeping Rygar\'s body compact.'),('LEAVE RETURN TIME','If the next target is close, wait for the disk rather than jumping into it with no weapon ready.'),('LISTEN TO THE AREA','Rygar has distinct outdoor, underground, water, castle, coin-heaven, intro and star/hurry selections.')],
 sources=['src/expanded.s','src/expanded_weapons.s','src/expanded_audio.s','docs/qa/rygar-world-palette-2026-10-22.md']),
dict(key='ryu',name='RYU HAYABUSA',kicker='EVERY WALL IS A DECISION',color='#5c60ac',number='10',
 intro='Ryu can turn a vertical wall into a pause in the action. Cling, climb and jump away, then decide whether a sword strike or a paid ninjitsu attack is the safer approach.',
 controls=[('A / B','Jump / slash with the sword.'),('Jump against a wall','Cling; Up/Down climbs. A jumps away.'),('Select or Up+B','Use the selected ninjitsu.'),('Jump Slash selected + air B','Spin the blade during the aerial attack.')],
 easy='Ryu arrived after the original six. He keeps the modern ninjitsu inventory and wall abilities. Easy adds ordinary stomps; it does not turn his sword and ninjitsu into a classic three-tier substitute.',
 hard='Same wall and weapon systems, with dangerous ordinary body contact. Use the sword or a valid Jump Slash instead of relying on a stomp. Wall contact is a movement tool, not invulnerability.',
 upgrades='Shuriken, Fire Wheel, windmill shuriken, Fire Dragon Ball and Jump Slash share ninjitsu. Shuriken costs 3; the others cost 5. Sword extension is separate. The scroll raises maximum ninjitsu from 50 to 99.',
 tips=[('CLIMB WITH AN EXIT','Before grabbing a wall, choose the side you intend to jump toward.'),('ONE SHARED POOL','Changing ninjitsu does not refill it. Small/big pickups restore 5/10.'),('SAVE THE SWORD','Your ordinary slash is free. Use it when a paid throw buys no extra safety.')],
 sources=['src/expanded.s','src/expanded_weapons.s','src/ryu_source_body.s','src/ryu_side_overlap.s','tools/reference/build_inventory.py']),
dict(key='sophia',name='SOPHIA III',kicker='A TANK WITH A VERTICAL PLAN',color='#b3519b',number='11',
 intro='Sophia starts as a mobile cannon and becomes a route machine. Hover, wall climbing and ceiling travel are separate equipment discoveries, so never assume a fresh tank can do all three.',
 controls=[('A / B','Jump / fire the main cannon. Up+B fires upward.'),('Select','Fire the selected standard or homing missile.'),('Hover owned: new air A','Start hover; hold A while fuel remains.'),('Wall / ceiling upgrades','Up attaches at a valid surface. Aim away to fire; A releases the ceiling.')],
 easy='Sophia retains the later inventory and movement upgrades. Easy permits ordinary descending stomps. Mushroom strengthens her main cannon; further block items expand her route options.',
 hard='The same equipment remains, but ordinary body landings hurt. Use cannon fire, missiles and acquired movement abilities to set up a clean landing. Armor is not blanket contact protection.',
 upgrades='Standard missiles launch a triplet and spend 3 from a 60-stock pool. Homing spends 1 from a 20-stock pool. Hover has an 8-unit supply and regenerates when inactive. Crusher further upgrades the cannon; wall and ceiling abilities are separate.',
 tips=[('B IS STILL THE CANNON','Select launches missiles; it does not replace B with a missile gun.'),('HOVER IS A RESERVE','Let a normal jump do the first part. Turn hover on when the route needs the extra lift.'),('CHECK THE UPGRADE','Ceiling attachment requires its own item after wall climbing. A new mushroom alone does not supply it.')],
 sources=['src/expanded.s','src/expanded_weapons.s','src/remaining_weapons.s','src/sophia_source_body.s','tools/reference/build_inventory.py']),
dict(key='scrooge',name='SCROOGE McDUCK',kicker='BOUNCE WITH PURPOSE',color='#2d899d',number='12',
 intro='Scrooge brings a cane and a pogo technique from DuckTales. This is a focused ROM addition: master the contact at the end of the cane instead of expecting DuckTales\' entire treasure and health system.',
 controls=[('A','Jump.'),('B','Swing the cane.'),('Down+B in the air','Engage pogo. Keep the input held to continue bouncing after landings.'),('Character select','Scrooge uses the slot formerly occupied by Luigi; Luigi is now Mario\'s alternate.')],
 easy='Ordinary descending enemy stomps are permitted, alongside the cane and pogo attacks. Scrooge retains his custom ROM toolkit in both modes rather than gaining a fictional 1.0 incarnation.',
 hard='Ordinary body landings hurt. Engage pogo early enough for the cane attack to reach the target. A cane hit and a body overlap are different contacts; do not treat every falling pose as protected.',
 upgrades='There is no selectable secondary-weapon inventory. Growth pickups use the ROM\'s custom power-state path; they do not add DuckTales\' object carrying, chest loot or health meter.',
 tips=[('SET POGO BEFORE CONTACT','Press Down+B while airborne, with enough height left to establish the attack.'),('LAND ON THE TIP','Center the cane over the enemy. Grazing a side can put Scrooge\'s body in danger.'),('B IS NOT A GRAB BUTTON','The implemented grounded action is a cane swing, not DuckTales\' full object interaction.')],
 sources=['src/scrooge.s','src/character_select.s','docs/reference/scrooge.json'])
]

ARSENAL=[
('SUPER ARM','8 on throw','Hold B against liftable empty masonry to pick it up; press B again to throw. Lifting needs 8 in reserve, but carrying and cancelling are free.'),
('METAL BLADE','4','Choose an eight-way direction with B. A defeated enemy may let the blade continue; a surviving target can stop it.'),
('HARD KNUCKLE','8','Fire, then steer Up/Down after startup. Its armor-piercing strength makes it a different tool from an ordinary pellet.'),
('PHARAOH SHOT','4 small / 8 charged','Hold B to grow the overhead charge, release to launch. Remember that its charge and the ordinary buster charge are different systems.'),
('CHARGE KICK','4','Select it and use Down+A. The paid kick is the weapon; merely owning it does not make every dash free damage.'),
('FLAME BLAST','4','Launch a seed that becomes a surface flame on contact. Aim the landing point of the seed.'),
('WATER SHIELD','16 to summon','B creates eight orbiting balls. After they finish appearing, a fresh press expands the shield. Dense attacks can still slow the NES.'),
('RUSH COIL','12 per spring','Mega Man only. Summoning is free with at least 4 energy. While Rush is present, B fires the ordinary buster. His spring clamps the remaining stock at zero.')]

QUICK=[
('Mario / Luigi','B run / fireball','None'),('Mega Man','Down+A slide; hold B charge','Hard: Select cycles weapon'),('Samus','Down Morph / crouch; ball B bomb','Hard: Select missile'),('Bill / Lance','D-pad+B directional gun','Pickup equips replacement gun'),('Link','Air Up/Down thrust; B sword','Select chosen special'),('Simon','Fresh second A; B whip','Select or Up+B subweapon'),('Pit','Flower: new air A, hold to fly','Select hammer'),('Rygar','B Diskarmor; Down+B low throw','None'),('Bass','Second A; Down+A dash','Select cycles weapon'),('Ryu','Wall cling/climb; B sword','Select or Up+B ninjitsu'),('Sophia III','Up+B cannon; air A hover if owned','Select chosen missile'),('Scrooge','Air Down+B pogo','No separate special')]
